    if (box1.maxY < box2.minY || box2.maxY < box1.minY) {
        separated = true;
    } else if (box1.maxY == box2.minY || box2.maxY == box1.minY) {
        adjacent = true;
    }
}

// Z axis
if (!separated) {
    if (box1.maxZ < box2.minZ || box2.maxZ < box1.minZ) {
        separated = true;
    } else if (box1.maxZ == box2.minZ || box2.maxZ == box1.minZ) {
        adjacent = true;
    }
}

if (separated) {
    return BoxRelation::Separated;
}
if (adjacent) {
    return BoxRelation::Adjacent;
}
return BoxRelation::Overlapped;

